		      if(lose.length)return ctx.setConfirm({title:'改用「'+choice.figure.name+'」？',body:'新建的「'+name+'」和它的'+lose.join('、')+'会被删除。',confirmLabel:'改用',danger:true,onConfirm:()=>apply(choice)});
