		        if(!runtime){runtime=ctx.binding.rpc('getLive2dRuntime',{});live2dRuntimes.set(ctx.binding,runtime);runtime.then(value=>{if(!live2dReady(value))live2dRuntimes.delete(ctx.binding);},()=>live2dRuntimes.delete(ctx.binding));}
