		              if (!live) return;
		              const s = result?.settings || {};
		              setModel(forkDanmakuModelInfo({ selection: s.modModels?.[FORK_DANMAKU_MOD]?.audience || null, foreground: s.defaultForegroundModel || null, catalog: result?.modelCatalog || [] }));
		              setModelError('');
