		    const y = below + bounds.height <= top + height - edge ? below : rect.top - gap - bounds.height;
		    popup.style.left = Math.max(left + edge, Math.min(align === 'end' ? rect.right - bounds.width : rect.left, left + width - bounds.width - edge)) + 'px';
